{
  "omision_de_tema_relevante": {
    "definicion": "Consiste en excluir deliberadamente información o asuntos de interés público del discurso mediático, creando una visión parcial de la realidad. La omisión puede deberse a intereses comerciales, políticos o ideológicos y genera una percepción distorsionada al no presentar todos los componentes relevantes de una situación.",
    "ejemplo": "En los reportes de prensa de junio 2024 sobre la crisis de agua en la región de Chihuahua, la mayoría de los medios nacionales resaltaron el turismo local y omitieron datos sobre la escasez de agua y la protesta de comunidades afectadas.",
    "como_detectarla": "1. Identificar el tema central de la noticia. 2. Revisar fuentes alternativas y comparar la información disponible. 3. Detectar la ausencia de datos relevantes que aparecen en otras fuentes."
  },
  "framing_de_conflicto_politico_en_lugar_de_tecnologico": {
    "definicion": "Redefine una cuestión principalmente tecnológica como una disputa ideológica o partidista, enfocando la atención en la confrontación política y minimizando el contenido técnico. Este encuadre dirige la interpretación del público hacia la polarización en vez de la comprensión del problema tecnológico.",
    "ejemplo": "Durante el debate del Congreso de EE. UU. sobre regulación de la IA en abril 2024, los titulares de los principales periódicos presentaron la discusión como una lucha entre demócratas y republicanos, relegando a segundo plano los aspectos técnicos de seguridad y ética.",
    "como_detectarla": "1. Analizar el lenguaje utilizado: busca términos de conflicto político. 2. Comparar con informes técnicos especializados sobre el mismo asunto. 3. Verificar si el enfoque principal es la rivalidad partidista en vez del contenido tecnológico."
  },
  "framing_de_noticias_locales_y_culturales": {
    "definicion": "Consiste en presentar acontecimientos locales o culturales como representativos de valores o identidades nacionales, amplificando su significado simbólico para influir en la percepción colectiva y reforzar narrativas de unidad o diferencia.",
    "ejemplo": "En julio 2024, la cobertura del Festival de la Guelaguetza en Oaxaca por la prensa nacional la describió como “el corazón de la cultura mexicana”, vinculándola a la identidad nacional y omitiendo su carácter regional y los debates internos sobre la gestión del evento.",
    "como_detectarla": "1. Identificar si la noticia se sitúa en un contexto local. 2. Observar la ampliación de su significado a nivel nacional o cultural. 3. Detectar la omisión de matices o controversias propias del contexto local."
  },
  "agenda_setting_centrado_en_politica_y_deporte": {
    "definicion": "Es la tendencia de los medios a priorizar la cobertura de asuntos políticos y deportivos, asignándoles mayor espacio y frecuencia, lo que orienta la agenda pública hacia esos temas en detrimento de otros como salud, educación o medio ambiente.",
    "ejemplo": "En los primeros meses de 2024, los principales canales de televisión en España dedicaron el 45 % de su tiempo de emisión a la campaña electoral y a la Liga de Fútbol, mientras que la cobertura de la reforma del sistema de salud recibió menos del 5 % del espacio total.",
    "como_detectarla": "1. Medir la proporción de tiempo o espacio dedicado a cada tema. 2. Comparar con la importancia social de los temas según indicadores externos (p.ej., encuestas de preocupación pública). 3. Identificar patrones de repetición y prominencia en la programación."
  },
  "infotainment_con_enfasis_en_figuras_publicas": {
    "definicion": "Mezcla de información y entretenimiento que prioriza el atractivo sensacionalista de las personalidades públicas sobre la sustancia de los hechos, usando estilo de espectáculo para captar la atención y diluir la profundidad informativa.",
    "ejemplo": "El programa matutino de televisión 'Buenos Días' del 12 de agosto 2024 dedicó 15 minutos a la polémica vida sentimental de la cantante Shakira, mientras que la cobertura sobre la nueva política climática del gobierno quedó relegada a un breve segmento de dos minutos.",
    "como_detectarla": "1. Evaluar la proporción entre contenido sobre figuras públicas y contenido sustantivo. 2. Analizar el tono: busca estilo de espectáculo, dramatización o comentarios sensacionalistas. 3. Verificar si la información esencial se presenta de forma superficial o se pospone."
  }
}
